class WorkoutExceptionHandler {
    @ExceptionHandler(WorkoutNotFoundException::class)
    fun handleNotFound(ex: WorkoutNotFoundException): ProblemDetail =
        ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.message ?: "Workout not found")

    @ExceptionHandler(WorkoutValidationException::class)
    fun handleValidation(ex: WorkoutValidationException): ProblemDetail =
        ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, ex.message ?: "Invalid workout")

    /**
     * The `@Valid` rejections — a `CreateWorkoutRequest` with no `scheduledDate`, a
     * `CopyWorkoutRequest` with no `targetDate`, an `UpdateWorkoutPreferenceRequest` with no
     * `displayUnit`. The **dispatch** is this module's own, so it does not depend on an advice in
     * another module happening to be unscoped; that dependency is exactly what
     * `AuthExceptionHandler` being scoped to `com.gymie.auth` removed. Spring resolves advice by
     * [RestControllerAdvice.assignableTypes], so this method cannot be shared — but the body it
     * answers with can, and is: [beanValidationProblemDetail] is the single definition, and `:auth`
     * and `:admin` call the same one.
     */
    @ExceptionHandler(MethodArgumentNotValidException::class)
    fun handleBeanValidation(ex: MethodArgumentNotValidException): ProblemDetail = beanValidationProblemDetail(ex)

    /**
     * Jackson wraps anything thrown while binding a request body — including the
     * [WorkoutValidationException] the field-scoped PATCH DTOs throw for an unknown key — inside
     * [HttpMessageNotReadableException], so it never reaches [handleValidation] and the client would
     * otherwise get the framework's bare `400` with no `detail`. Unwrapping it here is what keeps
     * *every* malformed-value rejection in `:workout` carrying a message the client can act on.
     *
     * A body that is unreadable for any other reason — truncated JSON, a missing non-null `kind`,
     * a wrong type — keeps its **detail-less** `400` unchanged. That absence is load-bearing: the
     * malformed-value suite tells a bind failure from a validation rejection precisely by whether a
     * `detail` is present, so this handler must add one only where there is a domain message to
     * add.
     */
    @ExceptionHandler(HttpMessageNotReadableException::class)
    fun handleUnreadableBody(ex: HttpMessageNotReadableException): ProblemDetail {
        val validation = validationCauseOf(ex) ?: return ProblemDetail.forStatus(HttpStatus.BAD_REQUEST)
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, validation.message ?: "Invalid workout")
    }

    private fun validationCauseOf(ex: Throwable): WorkoutValidationException? =
        generateSequence(ex) { current -> current.cause?.takeIf { it !== current } }
            .filterIsInstance<WorkoutValidationException>()
            .firstOrNull()

    @ExceptionHandler(WorkoutIllegalTransitionException::class)
    fun handleConflict(ex: WorkoutIllegalTransitionException): ProblemDetail =
        ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, ex.message ?: "Workout conflict")

